new_count = 0
updated_count = 0

for region, city, short_name, rtype, value, client_type, is_current in restrictions:
    # Check if exists
    existing = db.execute(
        'SELECT limit_value FROM restrictions WHERE region=? AND city IS ? AND limit_type=? AND is_current=1',
        (region, city, rtype)
    ).fetchone()
    
    if existing:
        # Update if changed
        if existing[0] != value:
            db.execute(
                'UPDATE restrictions SET limit_value=?, previous_value=?, updated_at=datetime("now") WHERE region=? AND city IS ? AND limit_type=? AND is_current=1',
                (value, existing[0], region, city, rtype)
            )
            updated_count += 1
    else:
        # Insert new
        db.execute(
            'INSERT INTO restrictions(region,city,network,limit_type,limit_value,client_type,is_current,source_url,source_date,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,datetime("now"),datetime("now"))',
            (region, city, short_name, rtype, value, client_type, is_current, URL, DATE)
        )
        new_count += 1

db.commit()
print(f'Restrictions: {new_count} new, {updated_count} updated')
print(f'Total active restrictions: {db.execute("SELECT COUNT(*) FROM restrictions WHERE is_current=1").fetchone()[0]}')
print(f'Total restrictions: {db.execute("SELECT COUNT(*) FROM restrictions").fetchone()[0]}')
print(f'Changes tracked: {db.execute("SELECT COUNT(*) FROM restrictions WHERE previous_value IS NOT NULL").fetchone()[0]}')

db.close()
